async function withSpinner<T>(label: string, task: () => Promise<T>): Promise<T> {
  const spinner = ora(label).start();
  const result = await task();
  spinner.succeed(`${label} done`);
  return result;
}

async function withPolling<T>(
  tick: () => void,
  intervalMs: number,
  run: () => Promise<T>,
): Promise<T> {
  const id = setInterval(tick, intervalMs);
  let result: T;
  try {
    result = await run();
  } catch (err) {
    console.error(`polling job failed: ${(err as Error).message}`);
    throw err;
  }
  clearInterval(id);
  return result;
}

function withTimeout<T>(promise: Promise<T>, ms: number, label = "operation"): Promise<T> {
  let timer: NodeJS.Timeout | undefined;
  const deadline = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
  });
  return Promise.race([promise, deadline]).finally(() => {
    if (timer) clearTimeout(timer);
  });
}

async function withRetry<T>(fn: () => Promise<T>, attempts = 3, baseDelayMs = 200): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (attempt < attempts) {
        await new Promise((resolve) => setTimeout(resolve, baseDelayMs * 2 ** (attempt - 1)));
      }
    }
  }
  throw lastError;
}

