async function withOpenFile<T>(path: string, fn: (fd: import("node:fs/promises").FileHandle) => Promise<T>): Promise<T> {
  const handle = await open(path, "r");
  try {
    return await fn(handle);
  } finally {
    await handle.close();
  }
}

async withSyncing<T>(action: () => Promise<T>): Promise<T> {
    this.isSyncing = true;
    this.lastError = null;
    const result = await action();
    this.isSyncing = false;
    return result;
  }

async withSnapshot<T>(action: (snapshot: Readonly<SyncStore>) => T): Promise<T> {
    const snapshot = Object.freeze({ ...this });
    return action(snapshot);
  }

async function withConnection<T>(pool: Pool, fn: (client: PoolClient) => Promise<T>): Promise<T> {
  const client = await pool.connect();
  const result = await fn(client);
  client.release();
  return result;
}

async function withTransaction<T>(pool: Pool, fn: (client: PoolClient) => Promise<T>): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const result = await fn(client);
    await client.query("COMMIT");
    client.release();
    return result;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  }
}

async function withReadOnlyClient<T>(pool: Pool, fn: (client: PoolClient) => Promise<T>): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query("SET TRANSACTION READ ONLY");
    return await fn(client);
  } finally {
    client.release();
  }
}

