async function withLock<T>(
  mutex: KeyedMutex,
  key: string,
  signal: AbortSignal,
  fn: () => Promise<T>,
): Promise<T | undefined> {
  const release = await mutex.acquire(key);
  if (signal.aborted) {
    return undefined;
  }
  try {
    return await fn();
  } finally {
    release();
  }
}

withKeyLock = <T>(mutex: KeyedMutex, key: string, fn: () => Promise<T>): Promise<T> =>
