  })

async function withTempDir<T>(prefix: string, fn: (dir: string) => Promise<T>): Promise<T> {
  const dir = await mkdtemp(join(tmpdir(), `${prefix}-`));
  const result = await fn(dir);
  await rm(dir, { recursive: true, force: true });
  return result;
}

async function withScratchDir<T>(prefix: string, fn: (dir: string) => Promise<T>): Promise<T> {
  await using scratch = await tempDir(prefix);
  return fn(scratch.path);
}

async function usingCursor<T extends Document>(
  collection: Collection<T>,
  filter: Filter<T>,
  pick: (doc: T) => boolean,
): Promise<T | null> {
  const cursor = collection.find(filter).batchSize(100);
  for await (const doc of cursor) {
    if (pick(doc as T)) return doc as T;
  }
  return null;
}

