function withAuth<P extends object>(Component: ComponentType<P>, role?: string) {
  return function Guarded(props: P) {
    const session = useSession();
    if (!session.user) return <a href="/login">Sign in</a>;
    if (role && !session.user.roles.includes(role)) return <p>Forbidden</p>;
    return <Component {...props} />;
  };
}

function withKeyboardShortcuts<P extends object>(Component: ComponentType<P>, bindings: Record<string, () => void>) {
  return function Bound(props: P) {
    useEffect(() => {
      const onKey = (event: KeyboardEvent) => {
        const handler = bindings[event.key];
        if (handler) handler();
      };
      window.addEventListener("keydown", onKey);
      return () => window.removeEventListener("keydown", onKey);
    }, []);
    return <Component {...props} />;
  };
}

withSaving = async (draft: string): Promise<void> => {
    pending.current?.abort();
    const controller = new AbortController();
    pending.current = controller;
    setState({ saving: true, error: null });
    await save(draft);
    if (controller.signal.aborted) return;
    setState({ saving: false, error: null });
  }

function withStyleOverride<P extends object>(Component: ComponentType<P>, styleId: string, css: string) {
  return function Styled(props: P) {
    useEffect(() => {
      const el = document.createElement("style");
      el.id = styleId;
      el.textContent = css;
      document.head.appendChild(el);
    }, []);
    return <Component {...props} />;
  };
}
